import psycopg


@app.get("/db")
def db():
    url = os.environ.get("DATABASE_URL")
    if not url:
        return {"database": "not configured"}
    with psycopg.connect(url, connect_timeout=3) as conn:
        version = conn.execute("select version()").fetchone()[0]
    return {"database": "ok", "version": version.split(",")[0]}

